source='''from collections import Counter


def transform(grid):
    height, width = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    seen = set()
    rectangles = []

    for row in range(height):
        for col in range(width):
            color = grid[row][col]
            if color == background or (row, col) in seen:
                continue

            stack = [(row, col)]
            seen.add((row, col))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < height and 0 <= nx < width and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r1 = min(y for y, _ in cells)
            r2 = max(y for y, _ in cells)
            c1 = min(x for _, x in cells)
            c2 = max(x for _, x in cells)
            area = (r2 - r1 + 1) * (c2 - c1 + 1)

            if len(cells) >= 3 and len(cells) / area >= 0.55:
                rectangles.append((color, r1, r2, c1, c2))
            elif len(cells) == 2 and area == 2:
                if r1 == r2:
                    if r2 + 1 < height:
                        r2 += 1
                    else:
                        r1 -= 1
                else:
                    if c2 + 1 < width:
                        c2 += 1
                    else:
                        c1 -= 1
                rectangles.append((color, r1, r2, c1, c2))

    output = [[background] * width for _ in range(height)]
    for color, r1, r2, c1, c2 in rectangles:
        for row in range(r1, r2 + 1):
            for col in range(c1, c2 + 1):
                output[row][col] = color
    return output
